/// Set of step stable IDs that count as "disposed".
/// Used by Disposed/Active Cases screens — case disposal is derived
/// from `last_step`, not a `status` column.
final Set<String> disposedStepIds = <String>{
  // Lower-court disposed-step lists follow the supplied source-file order.
  ..._lowerDisposedStepIds(districtCourtsCivilId, <String>[
    'Withdrawal',
    'Dismissal',
    'Allowed',
    'Rejected',
    'Rejected Right Away',
    'Maintainance Not Necessary',
    'Disposed',
  ]),
  ..._lowerDisposedStepIds(districtSessionsCriminalId, <String>[
    'Withdrawal under Section 248',
    'Allowed',
    'Rejected',
    'Rejected Right Away',
    'Conviction',
    'Acquittal',
    'Maintainance Not Necessary',
    'Disposed',
  ]),
  ..._lowerDisposedStepIds(metropolitanSessionsJudgeCriminalId, <String>[
    'Withdrawal under Section 248',
    'Allowed',
    'Rejected',
    'Rejected Right Away',
    'Conviction',
    'Acquittal',
    'Maintainance Not Necessary',
    'Disposed',
  ]),
  ..._lowerDisposedStepIds(chiefJudicialMagistrateId, <String>[
    'Withdrawal under Section 248',
    'Conviction',
    'Acquittal',
    'Maintainance Not Necessary',
    'Disposed',
  ]),
  ..._lowerDisposedStepIds(chiefMetropolitanMagistrateId, <String>[
    'Withdrawal under Section 248',
    'Conviction',
    'Acquittal',
    'Maintainance Not Necessary',
    'Disposed',
  ]),
  ..._lowerDisposedStepIds(executiveMagistrateId, <String>[
    'Remand',
    'Dismissal',
    'Withdrawal',
    'Rejected',
    'Maintainance Not Necessary',
    'Disposed',
  ]),
};

/// Localized labels for a single disposed step.
class DisposedStepLabels {
  /// Creates the labels for one disposed step.
  const DisposedStepLabels({required this.en, required this.bn});

  /// English label (e.g. "Withdrawal").
  final String en;

  /// Bengali label (e.g. "প্রত্যাহার").
  final String bn;
}

/// The disposed steps belonging to one court category.
class DisposedCategorySteps {
  /// Creates a court-category + its disposed steps pairing.
  const DisposedCategorySteps(this.categoryId, this.steps);

  /// Court-category stable ID (matches [SeedCategory.id]).
  final String categoryId;

  /// Disposed steps for this category, in the category's step order.
  final List<DisposedStepLabels> steps;
}

/// Lower-court category IDs, in the canonical display order from [seedCategories].
const List<String> _disposedCategoryOrder = <String>[
  districtCourtsCivilId,
  districtSessionsCriminalId,
  metropolitanSessionsJudgeCriminalId,
  chiefJudicialMagistrateId,
  chiefMetropolitanMagistrateId,
  executiveMagistrateId,
];

/// Disposed steps grouped by court category, in canonical display order.
///
/// Fully derived from [seedCategories] filtered by [disposedStepIds], so any
/// later change to the seeded disposed steps is reflected here automatically.
final List<DisposedCategorySteps> disposedStepsByCategory = List.unmodifiable(
  _disposedCategoryOrder.map((categoryId) {
    final category = seedCategories.firstWhere((c) => c.id == categoryId);
    final steps = category.steps
        .where((s) => disposedStepIds.contains(s.id))
        .map((s) => DisposedStepLabels(en: s.labelEn, bn: s.labelBn))
        .toList();
    return DisposedCategorySteps(categoryId, List.unmodifiable(steps));
  }).toList(),
);

/// Disposal keywords for Appellate & High Court Division cases.
///
/// Unlike lower courts, AD/HCD cases carry no seeded steps; disposal is detected
/// from the free-text `result` field. These terms are matched case-insensitively
/// against that field (see [CasesDao]), so the English forms are stored
/// lower-cased to match the SQL `LIKE` comparison.
const List<DisposedStepLabels> disposedResultTermLabels = <DisposedStepLabels>[
  DisposedStepLabels(en: 'Dismissed', bn: 'খারিজ'),
  DisposedStepLabels(en: 'Disposed', bn: 'নিষ্পত্তি'),
  DisposedStepLabels(en: 'Discharged', bn: 'অব্যহতি'),
];

// ---------------------------------------------------------------------------
// Comprehensive label maps (stable ID → label, both languages)
// These support runtime label resolution in AppTranslations.
// ---------------------------------------------------------------------------

/// All step stable IDs → English label.
final Map<String, String> stepLabelEn = Map.unmodifiable(
  Map.fromEntries(
    seedCategories.expand((c) => c.steps.map((s) => MapEntry(s.id, s.labelEn))),
  ),
);

/// All step stable IDs → Bengali label.
final Map<String, String> stepLabelBn = Map.unmodifiable(
  Map.fromEntries(
    seedCategories.expand((c) => c.steps.map((s) => MapEntry(s.id, s.labelBn))),
  ),
);

/// Step English label → Bengali label, per court category.
///
/// A case stores its steps as comma-joined step *names* (the form saves
/// `stepName`), so showing them in Bengali means mapping each name back through
/// the seed data. Only one name is shared across categories with different
/// labels ("Dismissal" is `খারিজ` in the civil district courts but `নথিজাত` for
/// the executive magistrates), but the map is keyed the same way as
/// [caseTypeLabelBnByCourtCategory] so the two stay symmetrical.
final Map<String, Map<String, String>> stepLabelBnByCourtCategory =
    Map.unmodifiable(
      Map.fromEntries(
        seedCategories.map(
          (category) => MapEntry(
            category.id,
            Map<String, String>.unmodifiable(<String, String>{
              for (final step in category.steps) step.labelEn: step.labelBn,
            }),
          ),
        ),
      ),
    );

/// Every representation a stored step token can take → its Bengali label.
///
/// A case stores its steps by *name*, but rows written by older builds or by a
/// hand-edited step can hold the stable ID, the Bengali label, or a name that
/// differs only in case. Keying the lookup by all of those means any of them
/// still renders in the active language; a token found nowhere is user text and
/// is shown exactly as stored. The first category in seed order wins, so the
/// result is deterministic.
final Map<String, String> stepLabelBnByToken = _stepLabelsByToken(stepLabelBn);

/// Every representation a stored step token can take → its English label.
/// Mirrors [stepLabelBnByToken] for the English UI.
final Map<String, String> stepLabelEnByToken = _stepLabelsByToken(stepLabelEn);

Map<String, String> _stepLabelsByToken(Map<String, String> labelById) {
  final byToken = <String, String>{};
  for (final step in seedCategories.expand((c) => c.steps)) {
    final label = labelById[step.id];
    if (label == null) continue;
    for (final token in <String>[step.id, step.labelEn, step.labelBn]) {
      byToken.putIfAbsent(token, () => label);
      byToken.putIfAbsent(token.toLowerCase(), () => label);
    }
  }
  return Map<String, String>.unmodifiable(byToken);
}

/// Display names (both languages) of every disposed step.
/// A case's `last_step` stores comma-joined step names, so disposal is detected
/// by matching any of these names. Derived from [disposedStepIds].
final Set<String> disposedStepNames = disposedStepIds
    .expand((id) => [stepLabelEn[id], stepLabelBn[id]])
    .whereType<String>()
    .toSet();

/// All case type stable IDs → English label.
final Map<String, String> caseTypeLabelEn = Map.unmodifiable(
  Map.fromEntries(
    seedCategories.expand(
      (c) => c.allCaseTypes.map((ct) => MapEntry(ct.id, ct.labelEn)),
    ),
  ),
);

/// All case type stable IDs → Bengali label.
final Map<String, String> caseTypeLabelBn = Map.unmodifiable(
  Map.fromEntries(
    seedCategories.expand(
      (c) => c.allCaseTypes.map((ct) => MapEntry(ct.id, ct.labelBn)),
    ),
  ),
);

/// Case type English label → Bengali label, per court category.
///
/// `cases.case_type` stores the case type *name* (the English label of the row
/// it was picked from) rather than its stable ID, so showing it in Bengali
/// means mapping that name back through the seed data. Twenty of the 160 names
/// are shared by several court categories with different Bengali labels
/// ("Misc Case" is `ছানী মিছ-` for the civil district courts but `বিবিধ মোকদ্দমা-`
/// for the executive magistrates), which is why the court category is the key.
final Map<String, Map<String, String>> caseTypeLabelBnByCourtCategory =
    Map.unmodifiable(
      Map.fromEntries(
        seedCategories.map(
          (category) => MapEntry(
            category.id,
            Map<String, String>.unmodifiable(<String, String>{
              for (final caseType in category.allCaseTypes)
                caseType.labelEn: caseType.labelBn,
            }),
          ),
        ),
      ),
    );

/// Case type English label → Bengali label, ignoring the court category.
///
/// Fallback for surfaces that do not know the case's court category. When a
/// name is shared, the first category in seed order wins, so the result is
/// deterministic rather than arbitrary.
final Map<String, String> caseTypeLabelBnByEnName = () {
  final byName = <String, String>{};
  for (final caseType in seedCategories.expand((c) => c.allCaseTypes)) {
    byName.putIfAbsent(caseType.labelEn, () => caseType.labelBn);
  }
  return Map<String, String>.unmodifiable(byName);
}();

/// All on-behalf stable IDs → English label.
final Map<String, String> onBehalfLabelEn = Map.unmodifiable(
  Map.fromEntries(
    seedCategories.expand(
      (c) => c.onBehalfs.map((o) => MapEntry(o.id, o.labelEn)),
    ),
  ),
);

